from __future__ import annotations
import inspect
import re
from fastapi.responses import HTMLResponse
from fastapi.routing import request_response


def install(app):
    route = next((r for r in app.router.routes if getattr(r, 'path', None) == '/'), None)
    if route is None or not hasattr(route, 'endpoint'):
        return
    original = route.endpoint
    if getattr(original, '_fs_ui_final_v12', False):
        return

    def endpoint(*args, **kwargs):
        response = original() if not inspect.signature(original).parameters else original(*args, **kwargs)
        html = response.body.decode('utf-8') if isinstance(response, HTMLResponse) and isinstance(response.body, (bytes, bytearray)) else str(response)
        html = re.sub(r'<section class="hero">.*?</section>', '', html, count=1, flags=re.S)
        html = re.sub(r'<section class="card run-card">.*?</section>', '', html, count=1, flags=re.S)
        html = re.sub(r'<script id="fs-final-control-js">.*?</script>', '', html, flags=re.S)
        html = re.sub(r'<script id="fs-ui-v11-js">.*?</script>', '', html, flags=re.S)
        html = re.sub(r'<script id="fs-ui-v12-js">.*?</script>', '', html, flags=re.S)

        command_card = r'''<section class="card fs-command-card" id="fsCommandCard">
<div class="title">⚡ УПРАВЛЕНИЕ БОТОМ</div>
<div class="fs-command-grid">
  <div class="fs-command-mode"><div class="fs-command-label">PAPER</div><button id="paperSwitch" class="run-switch" type="button"><span class="run-dot"></span><b id="paperSwitchText">OFF</b></button><div id="paperStatus" class="run-status">PAPER остановлен</div><div id="paperTimer" class="run-timer">00:00:00</div></div>
  <div class="fs-command-mode"><div class="fs-command-label">LIVE</div><button id="liveSwitch" class="run-switch" type="button"><span class="run-dot"></span><b id="liveSwitchText">OFF</b></button><div id="liveStatus" class="run-status">LIVE остановлен</div><div id="liveTimer" class="run-timer">00:00:00</div><button id="fsEmergency" class="fs-emergency" type="button">⛔ EMERGENCY STOP</button></div>
</div></section>'''
        html = html.replace('<main class="wrap">', '<main class="wrap">' + command_card, 1)

        css = r'''<style id="fs-ui-v12-css">
.fs-command-card{padding:8px 10px;margin:7px 0}.fs-command-card>.title{font-size:14px;margin-bottom:5px}.fs-command-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.fs-command-mode{border:1px solid #451015;border-radius:9px;background:#08090a;padding:7px;text-align:center;min-width:0}.fs-command-label{font-size:11px;font-weight:900;color:#ddd;margin-bottom:3px}.fs-command-mode .run-switch{display:inline-flex;align-items:center;justify-content:center;gap:6px;width:auto;min-width:62px;padding:5px 9px;margin:0;border:1px solid #555;background:#18191b;color:#aaa;border-radius:999px;font-weight:900;cursor:pointer;touch-action:manipulation}.fs-command-mode .run-switch.on{background:#0e793b;border-color:#22e36f;color:#fff}.fs-command-mode .run-dot{width:8px;height:8px;border-radius:50%;background:#666}.fs-command-mode .run-switch.on .run-dot{background:#22e36f;box-shadow:0 0 7px #22e36f}.fs-command-mode .run-status{margin-top:3px;color:#888;font-size:10px;line-height:1.1}.fs-command-mode .run-status.on{color:#22e36f;font-weight:900}.fs-command-mode .run-timer{font-variant-numeric:tabular-nums;font-size:15px;font-weight:900;color:#fff;margin:3px 0 0}.fs-emergency{width:100%;border:0;border-radius:7px;background:#292a2d;color:#fff;font-weight:900;font-size:10px;padding:5px 4px;margin-top:4px;cursor:pointer}.pnl-card .pnlrow{grid-template-columns:repeat(4,minmax(0,1fr))!important}.fs-hypo-label{color:#aaa}.fs-hypo-value{display:block;color:#65f28d;font-weight:900;margin-top:3px}.bot-summary{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:5px!important;align-items:center}.bot-summary>div{white-space:nowrap;font-size:10px}.bot-summary b{display:inline!important;font-size:14px!important;margin-left:3px!important}#slots{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:6px}.slot{padding:6px!important}.slot .mini{display:none!important}.slot .input{padding:7px!important;margin:2px 0!important;font-size:12px}.slot .btn{padding:6px!important;font-size:10px;margin-top:4px}.slot .muted{font-size:9px}.fs-slot-row{display:grid;grid-template-columns:1fr 54px;gap:5px;align-items:center}.fs-slot-tf{width:100%;background:#151719;color:#ffd04d;border:1px solid #3b3c40;border-radius:6px;padding:5px 3px;font-size:10px;font-weight:900}.fs-top10-final{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:6px}.fs-top10-final .fs-card{border:1px solid #451015;border-radius:10px;background:#08090a;padding:7px;min-width:0}.fs-top10-final .rank{display:flex;justify-content:space-between;gap:5px;font-weight:900;color:#fff}.fs-top10-final .score{color:#65f28d;border:1px solid #1d8d46;background:#082514;border-radius:5px;padding:2px 5px}.fs-top10-final .meta{display:grid;grid-template-columns:1fr 1fr;gap:2px 5px;margin-top:4px;color:#aaa;font-size:9px}.fs-top10-final .profit{color:#65f28d;font-weight:900;margin-top:4px}.fs-price-red{color:#ff4b4b;font-weight:900}.fs-sell-band{color:#bbb;font-size:9px;margin-top:3px}.fs-top10-final select{width:100%;margin-top:5px;background:#151719;color:#ffd04d;border:1px solid #3b3c40;border-radius:5px;padding:4px;font-weight:800;font-size:9px}.fs-top10-final button{width:100%;margin-top:5px;border:1px solid #ffb300;background:#281d06;color:#ffd04d;border-radius:6px;padding:6px;font-weight:900;font-size:9px}.fs-top10-final button.selected{background:#08783a;border-color:#22e36f;color:#fff}@media(max-width:600px){.fs-command-grid{grid-template-columns:1fr 1fr}.fs-command-mode{padding:6px 4px}.fs-command-label{font-size:10px}.fs-command-mode .run-switch{min-width:58px;padding:5px 6px;font-size:11px}.fs-command-mode .run-timer{font-size:14px}.fs-emergency{font-size:9px}.pnl-card .pnlrow{grid-template-columns:repeat(4,minmax(0,1fr))!important}.bot-summary>div{font-size:8px}.bot-summary b{font-size:12px!important}.slot .input{font-size:11px!important}.fs-slot-tf{font-size:9px}}
</style>'''
        html = html.replace('</style></head>', css + '</style></head>', 1)

        js = r'''<script id="fs-ui-v12-js">
(function(){
 const $=id=>document.getElementById(id),TF_KEY='fsRecommendationTimeframes',SLOT_KEY='fsFastScalperSlotsV2',tfState=JSON.parse(localStorage.getItem(TF_KEY)||'{}'),timers={PAPER:null,LIVE:null};
 function normalize(){if(typeof slots==='undefined')return;let saved=null;try{saved=JSON.parse(localStorage.getItem(SLOT_KEY)||'null')}catch(e){}if(Array.isArray(saved)&&saved.length&&!slots.some(x=>x&&x.p)){slots.length=0;saved.forEach(x=>slots.push(x))}while(slots.length<10)slots.push({p:'',v:0,input:'pct',mode:'LIVE',tf:'3m'});if(slots.length>10)slots.length=10;slots.forEach(x=>{x.p=String(x.p||'').toUpperCase().replace('-', '/');x.tf=x.tf||tfState[x.p]||'3m';x.input='pct';x.mode=x.mode||'LIVE'})}
 function persist(){normalize();try{localStorage.setItem(SLOT_KEY,JSON.stringify(slots))}catch(e){}if(typeof save==='function')save()}
 function decorate(){normalize();document.querySelectorAll('#slots .slot').forEach((row,i)=>{if(row.querySelector('.fs-slot-row'))return;const pair=row.querySelector('input[placeholder^="ПАРА"]'),num=row.querySelector('input[type="number"]');if(!pair||!num)return;const wrap=document.createElement('div');wrap.className='fs-slot-row';pair.parentNode.insertBefore(wrap,pair);wrap.appendChild(pair);const s=document.createElement('select');s.className='fs-slot-tf';s.innerHTML='<option value="1m">1 мин</option><option value="3m">3 мин</option><option value="5m">5 мин</option>';s.value=slots[i]?.tf||'3m';s.onchange=()=>{slots[i].tf=s.value;tfState[slots[i].p]=s.value;localStorage.setItem(TF_KEY,JSON.stringify(tfState));persist()};wrap.appendChild(s)})}
 if(typeof window.render==='function'){const old=window.render;window.render=function(){old();normalize();decorate()}}
 window.pick=function(symbol){normalize();symbol=String(symbol||'').trim().toUpperCase().replace('-', '/');if(!symbol)return;const same=slots.filter(x=>x.p===symbol),tf=String(tfState[symbol]||'3m');if(same.length){const old=same.map(x=>x.tf||'3m').join(', ');if(!confirm(symbol+' уже выбрана на таймфрейме '+old+'.\nВыбрать ту же пару ещё раз на '+tf+'?'))return}const idx=slots.findIndex(x=>!x.p);if(idx<0){alert('Все 10 торговых слотов заняты.');return}slots[idx]={p:symbol,v:0,input:'pct',mode:'LIVE',tf:tf};const chosen=slots.filter(x=>x.p),each=Math.round((100/chosen.length)*100)/100;chosen.forEach(x=>x.v=each);persist();render();decorate();setTimeout(renderRadar,50)};
 function cfg(){normalize();const a=slots.map((x,i)=>({x,i})).filter(z=>z.x.p);return{capital:cap(),pairs:a.map(z=>z.x.p),allocations:a.map(z=>Number(z.x.v)||0),timeframes:a.map(z=>z.x.tf||'3m'),target_pnl_per_min_per_100:1.73,target_usdt:.30,min_usdt:.15,sl_pct:.5,max_hold:180,fee_pct:.10,timeframe:'3m'}}
 async function run(mode){const c=cfg(),total=c.allocations.reduce((a,b)=>a+b,0);if(!c.pairs.length){alert('Нет выбранных '+mode+' позиций');return}if(total<=0||total>100.0001){alert(mode+': сумма долей должна дать 100%. Сейчас '+total.toFixed(2)+'%.');return}if(mode==='LIVE'){c.api_key=$('key')?.value||'';c.api_secret=$('secret')?.value||'';if(!c.api_key||!c.api_secret){alert('Для LIVE нужны Binance API Key и Secret');return}}try{const r=await fetch('/api/'+mode.toLowerCase()+'/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(c),cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok||d.running===false){alert(d.detail||('Не удалось запустить '+mode));return}localStorage.setItem('fsLastReportMode',mode);paint(mode,true,d.started_at)}catch(e){alert('Ошибка запуска '+mode+': '+e.message)}}
 async function halt(mode){try{const r=await fetch('/api/'+mode.toLowerCase()+'/stop',{method:'POST',cache:'no-store'});paint(mode,false);return r.ok}catch(e){return false}}async function emergency(){await Promise.all(['PAPER','LIVE'].map(m=>fetch('/api/'+m.toLowerCase()+'/emergency-stop',{method:'POST',cache:'no-store'}).catch(()=>null)));paint('PAPER',false);paint('LIVE',false)}
 function paint(mode,on,started){const low=mode.toLowerCase(),sw=$(low+'Switch'),tx=$(low+'SwitchText'),st=$(low+'Status'),tm=$(low+'Timer');if(sw)sw.classList.toggle('on',!!on);if(tx)tx.textContent=on?'ON':'OFF';if(st){st.textContent=mode+' '+(on?'работает':'остановлен');st.classList.toggle('on',!!on)}clearInterval(timers[mode]);if(!on){if(tm)tm.textContent='00:00:00';return}const key=mode==='PAPER'?'fsRunStartPaper':'fsRunStartLive',ts=(Number(started)||Number(localStorage.getItem(key))/1000||Date.now()/1000)*1000;localStorage.setItem(key,String(ts));const tick=()=>{const sec=Math.max(0,Math.floor((Date.now()-ts)/1000)),h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;if(tm)tm.textContent=[h,m,s].map(x=>String(x).padStart(2,'0')).join(':')};tick();timers[mode]=setInterval(tick,1000)}
 async function sync(mode){try{const r=await fetch('/api/session/report/'+mode,{cache:'no-store'});if(!r.ok)return;const d=await r.json();paint(mode,!!d.running,d.started_at)}catch(e){}}
 function compactMetrics(){const bs=document.querySelector('.bot-summary');if(bs)bs.innerHTML='<div>🤖 БАЛАНС БОТА <b id="bot">—</b></div><div>➕ ВОЗМОЖНО ПРИВЛЕЧЬ <b id="extra">—</b></div><div>💰 НАКОПЛЕНО <b id="accumulated">—</b></div>';const row=document.querySelector('.pnl-card .pnlrow');if(row&&!$('hypo')){const d=document.createElement('div');d.className='fs-hypo-label';d.innerHTML='Hypothetical Net<br><b id="hypo" class="fs-hypo-value">0.0000 USDT</b>';row.appendChild(d)}}
 async function metrics(){try{compactMetrics();const mode=localStorage.getItem('fsLastReportMode')||'PAPER',d=await fetch('/api/session/report/'+mode,{cache:'no-store'}).then(r=>r.json());[['bot',d.bot_balance_usdt],['extra',d.available_to_attract_usdt],['accumulated',d.accumulated_profit_usdt]].forEach(([id,v])=>{if($(id))$(id).textContent=Number(v||0).toFixed(4)+' USDT'})}catch(e){}}
 function rows(d){return(d.candidates20||d.top10||d.top5||[]).slice(0,10)}
 function renderRadarRows(rs){const top=$('top');if(!top)return;top.innerHTML='<div class="fs-top10-final">'+rs.map((x,i)=>{const s=String(x.symbol||'—'),score=Number(x.score),price=Number(x.price||0),tf=String(tfState[s]||'3m'),low=price*.90,high=price*1.20,selected=typeof slots!=='undefined'&&slots.some(z=>z.p===s);return '<div class="fs-card"><div class="rank"><span>🔥 #'+(i+1)+' '+s+'</span><span class="score">'+(Number.isFinite(score)?score.toFixed(0):'—')+'</span></div><div class="meta"><span>Hot: '+(Number(x.hot_market_score)||0).toFixed(0)+'</span><span>Flow: '+((Number(x.buy_ratio)||0)*100).toFixed(0)+'%</span><span>1–3m: '+(Number(x.change_3m_pct)||0).toFixed(3)+'%</span><span>$/мин/$100: <b class="profit">$'+(Number(x.expected_pnl_per_min_100)||0).toFixed(2)+'</b></span><span>Цена сейчас: <b class="fs-price-red">'+(price?price.toPrecision(9):'—')+'</b></span><span>Сигнал: '+String(x.signal||'WAIT')+'</span></div><div class="fs-sell-band">Ориентир курса −10%: '+(price?low.toPrecision(8):'—')+' • +20%: '+(price?high.toPrecision(8):'—')+'</div><div class="profit">Прогноз $100: '+(Number(x.expected_pnl_per_min_100)||0).toFixed(4)+' $/мин</div><select data-symbol="'+s+'" class="fs-radar-tf"><option value="1m" '+(tf==='1m'?'selected':'')+'>1 мин</option><option value="3m" '+(tf==='3m'?'selected':'')+'>3 мин</option><option value="5m" '+(tf==='5m'?'selected':'')+'>5 мин</option></select><button class="top-select '+(selected?'selected':'')+'" data-symbol="'+s+'">'+(selected?'✓ ВЫБРАНО':'ВЫБРАТЬ')+'</button></div>'}).join('')+'</div>';top.querySelectorAll('.fs-radar-tf').forEach(el=>el.onchange=()=>{tfState[el.dataset.symbol]=el.value;localStorage.setItem(TF_KEY,JSON.stringify(tfState));renderRadar()});top.querySelectorAll('.top-select').forEach(b=>b.onclick=()=>window.pick(b.dataset.symbol))}
 async function renderRadar(){try{const d=await fetch('/api/recommendations?limit=20',{cache:'no-store'}).then(r=>r.json());renderRadarRows(rows(d))}catch(e){}}
 function boot(){normalize();persist();compactMetrics();decorate();renderRadar();sync('PAPER');sync('LIVE');metrics();setInterval(()=>{sync('PAPER');sync('LIVE');metrics();renderRadar()},5000)}
 $('paperSwitch')?.addEventListener('click',()=>run('PAPER'));$('liveSwitch')?.addEventListener('click',()=>run('LIVE'));$('fsEmergency')?.addEventListener('click',emergency);
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else setTimeout(boot,0);
})();
</script>'''
        html = html.replace('</body>', js + '</body>', 1)
        headers = dict(getattr(response, 'headers', {}) or {})
        headers.pop('content-length', None); headers.pop('Content-Length', None); headers.pop('content-type', None); headers.pop('Content-Type', None)
        headers['Cache-Control']='no-store, no-cache, must-revalidate, max-age=0'
        return HTMLResponse(content=html,status_code=getattr(response,'status_code',200),headers=headers,media_type='text/html')

    endpoint._fs_ui_final_v12=True
    route.endpoint=endpoint
    route.app=request_response(endpoint)
